    private static void UebernehmeErgebnis(KiVorschlag vorschlag, KiVorschlagErgebnis ergebnis, List<Abteilung> abteilungen)
    {
        vorschlag.VorgeschlagenerTitel = ergebnis.VorgeschlagenerTitel;
