        vorschlag.ManuellePruefungErforderlich = ergebnis.ManuellePruefungErforderlich;
        vorschlag.Pruefstatus = Pruefstatus.Ausstehend;
    }

    private static AnfrageListItemDto ToListItemDto(Anfrage anfrage) => new(
