  const response = await fetch(`${API_BASE_URL}/api/anfragen`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  })
  if (!response.ok) {
    throw new Error(`Anfrage konnte nicht erstellt werden (Status ${response.status}).`)
  }
}

