1	using FlowDesk.Api.Data;
2	using FlowDesk.Api.Dtos;
3	using FlowDesk.Api.Models;
4	using FlowDesk.Api.Services;
5	using Microsoft.AspNetCore.Mvc;
6	using Microsoft.EntityFrameworkCore;
7	
8	namespace FlowDesk.Api.Controllers;
9	
10	[ApiController]
11	[Route("api/anfragen")]
12	public class AnfragenController(FlowDeskDbContext db, IKiVorschlagService kiService) : ControllerBase
13	{
14	    [HttpGet]
15	    public async Task<ActionResult<List<AnfrageListItemDto>>> GetAlle()
16	    {
17	        var anfragen = await db.Anfragen
18	            .Include(a => a.Standort)
19	            .OrderByDescending(a => a.ErstelltAm)
20	            .ToListAsync();
21	
22	        return Ok(anfragen.Select(ToListItemDto).ToList());
23	    }
24	
25	    [HttpGet("{id:int}")]
26	    public async Task<ActionResult<AnfrageDetailDto>> GetById(int id)
27	    {
28	        var anfrage = await LadeAnfrageMitDetails(id);
29	        if (anfrage is null) return NotFound();
30	
31	        return Ok(ToDetailDto(anfrage));
32	    }
33	
34	    [HttpPost]
35	    public async Task<ActionResult<AnfrageDetailDto>> Erstellen(AnfrageErstellenRequest request)
36	    {
37	        var standort = await db.Standorte.FindAsync(request.StandortId);
38	        if (standort is null) return BadRequest("Unbekannter Standort.");
39	
40	        var jetzt = DateTime.UtcNow;
41	        var anfrage = new Anfrage
42	        {
43	            OriginalText = request.OriginalText,
44	            StandortId = standort.Id,
45	            Standort = standort,
46	            Status = AnfrageStatus.Neu,
47	            ErstelltAm = jetzt,
48	            AktualisiertAm = jetzt
49	        };
50	
51	        db.Anfragen.Add(anfrage);
52	        await db.SaveChangesAsync();
53	
54	        return CreatedAtAction(nameof(GetById), new { id = anfrage.Id }, ToDetailDto(anfrage));
55	    }
56	
57	    [HttpPatch("{id:int}/status")]
58	    public async Task<ActionResult<AnfrageDetailDto>> StatusAktualisieren(int id, StatusAktualisierenRequest request)
59	    {
60	        var anfrage = await LadeAnfrageMitDetails(id);
61	        if (anfrage is null) return NotFound();
62	
63	        anfrage.Status = request.Status;
64	        anfrage.AktualisiertAm = DateTime.UtcNow;
65	        await db.SaveChangesAsync();
66	
67	        return Ok(ToDetailDto(anfrage));
68	    }
69	
70	    [HttpPost("{id:int}/ki-analyse")]
71	    public async Task<ActionResult<KiVorschlagDto>> KiAnalyse(int id)
72	    {
73	        var anfrage = await db.Anfragen
74	            .Include(a => a.KiVorschlag)
75	            .ThenInclude(k => k!.VorgeschlageneAbteilungen)
76	            .FirstOrDefaultAsync(a => a.Id == id);
77	
78	        if (anfrage is null) return NotFound();
79	
80	        var ergebnis = kiService.Analysiere(anfrage.OriginalText);
81	        var abteilungen = await db.Abteilungen
82	            .Where(a => ergebnis.VorgeschlageneAbteilungen.Contains(a.Name))
83	            .ToListAsync();
84	
85	        if (anfrage.KiVorschlag is null)
86	        {
87	            var vorschlag = new KiVorschlag { AnfrageId = anfrage.Id };
88	            UebernehmeErgebnis(vorschlag, ergebnis, abteilungen);
89	            db.KiVorschlaege.Add(vorschlag);
90	            anfrage.KiVorschlag = vorschlag;
91	        }
92	        else
93	        {
94	            UebernehmeErgebnis(anfrage.KiVorschlag, ergebnis, abteilungen);
95	        }
96	
97	        await db.SaveChangesAsync();
98	        return Ok(ToVorschlagDto(anfrage.KiVorschlag));
99	    }
100	
101	    [HttpPost("{id:int}/ki-entscheidung")]
102	    public async Task<ActionResult<AnfrageDetailDto>> KiEntscheidung(int id, KiEntscheidungRequest request)
103	    {
104	        var anfrage = await LadeAnfrageMitDetails(id);
105	        if (anfrage is null) return NotFound();
106	        if (anfrage.KiVorschlag is null) return BadRequest("Es liegt noch kein KI-Vorschlag für diese Anfrage vor.");
107	
108	        var vorschlag = anfrage.KiVorschlag;
109	
110	        switch (request.Pruefstatus)
111	        {
112	            case Pruefstatus.Angenommen:
113	                anfrage.Titel = vorschlag.VorgeschlagenerTitel;
