      .then(setAnfragen)
      .catch((error: Error) => setFehler(error.message))
      .finally(() => setLaedt(false))
  }

  useEffect(() => {
    ladeAnfragen()
  }, [])

  const handleLoeschen = async (id: number) => {
    if (!window.confirm('Möchtest du diese Anfrage wirklich löschen?')) return

    try {
      await loescheAnfrage(id)
      ladeAnfragen()
    } catch (error) {
      setFehler((error as Error).message)
    }
  }

  if (ansicht === 'formular') {
    return (
      <main>
        <NeueAnfrageFormular
          onAbbrechen={() => setAnsicht('liste')}
          onErstellt={() => {
            setAnsicht('liste')
            ladeAnfragen()
          }}
        />
      </main>
    )
  }

  if (ansicht === 'detail' && ausgewaehlteId !== null) {
    return (
      <main>
        <AnfrageDetailAnsicht id={ausgewaehlteId} onZurueck={() => {setAnsicht('liste')
