:root {
  --text: #6b6375;
  --text-h: #08060d;
  --bg: #fff;
  --border: #e5e4e7;
  --row-hover: #f7f6fa;

  --sans: system-ui, 'Segoe UI', Roboto, sans-serif;

  font: 16px/145% var(--sans);
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
}

@media (prefers-color-scheme: dark) {
  :root {
    --text: #9ca3af;
    --text-h: #f3f4f6;
    --bg: #16171d;
    --border: #2e303a;
    --row-hover: #1c1d24;
  }
}

body {
  margin: 0;
}

#root {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 16px;
}

h1 {
  font-size: 28px;
  color: var(--text-h);
  margin: 0;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

button {
  font: inherit;
  padding: 8px 16px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--text-h);
  color: var(--bg);
  cursor: pointer;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

th,
td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

th {
  color: var(--text-h);
  font-weight: 600;
}

tbody tr:hover {
  background: var(--row-hover);
}

tr.klickbar {
  cursor: pointer;
}

.detail {
  display: grid;
  grid-template-columns: 160px 1fr;
  row-gap: 12px;
  column-gap: 16px;
  margin-top: 16px;
}

.detail dt {
  color: var(--text-h);
  font-weight: 600;
}

.detail dd {
  margin: 0;
}

.detail .original-text {
  white-space: pre-wrap;
}

.ki-bereich {
  margin-top: 32px;
  padding-top: 24px;
  border-top: 1px solid var(--border);
}

.ki-bereich h2 {
  font-size: 20px;
  color: var(--text-h);
  margin: 0 0 12px;
}

form {
  max-width: 480px;
  margin-top: 16px;
}

.feld {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}

.feld label {
  color: var(--text-h);
  font-weight: 600;
}

.feld select,
.feld textarea,
.feld input[type='text'] {
  font: inherit;
  padding: 8px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text-h);
}

.checkbox-feld {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 400;
}

.aktionen {
  display: flex;
  gap: 12px;
}

.aktionen button[type='button'] {
  background: var(--bg);
  color: var(--text-h);
}

