}

p {
  margin: 0;
  color: var(--text-secondary);
}

[role='alert'] {
  color: var(--danger);
  font-size: 13px;
  margin-top: 6px;
}

h1 {
  font-size: 28px;
  font-weight: 700;
  color: var(--text);
  margin: 0;
  letter-spacing: -0.01em;
}

h2 {
  font-size: 18px;
