tr.klickbar {
  cursor: pointer;
}

th.sortierbar {
  cursor: pointer;
  user-select: none;
}

.sort-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.sort-pfeil {
  display: inline-flex;
  align-items: center;
